import Foundation

/// What may be recorded. Pure, so the security rules are tested without a pasteboard.
enum PasteboardFilter {
    /// nspasteboard.org markers set by password managers and system helpers.
    static let blockedTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
    ]
    static let maxTextBytes = 1_048_576          // 1 MB
    static let maxImageBytes = 10 * 1_048_576    // 10 MB

    static func shouldRecord(types: [String], frontmostBundleID: String?, excluded: Set<String>) -> Bool {
        guard !types.isEmpty else { return false }
        if types.contains(where: blockedTypes.contains) { return false }
        if let app = frontmostBundleID, excluded.contains(app) { return false }
        return true
    }

    static func textAllowed(byteCount: Int) -> Bool { byteCount <= maxTextBytes }
    static func imageAllowed(byteCount: Int) -> Bool { byteCount <= maxImageBytes }
}
